import { MeshBasicNodeMaterial } from 'three/webgpu';
import { gsap } from 'gsap';

export default function createNode(config, ctx) {
  const { THREE } = ctx;
  const group = new THREE.Group();

  // --- Parse config ---
  const colors = config.intent?.visualSpec?.colors || config.colors;
  const paper = colors?.paper || '#e8ecf2';
  const textContent = config.textContent ?? config.intent?.visualSpec?.textContent ?? [];
  const headlineItem = textContent.find(item => item.role === 'headline');
  const headlineText = headlineItem?.text || 'Features 1';
  const headlineFontSize = headlineItem?.typography?.fontSize ?? 39;

  // --- Plane geometry (aspect ratio from source rect: 512x320 → 1.6) ---
  const planeWidth = 2.5;
  const planeHeight = planeWidth / (512 / 320); // ≈ 1.5625
  const geometry = new THREE.PlaneGeometry(planeWidth, planeHeight);

  // --- Material with placeholder map (will be replaced) ---
  const material = new MeshBasicNodeMaterial({
    color: 0x16161d, // fallback ink color
    transparent: true,
  });

  const plane = new THREE.Mesh(geometry, material);
  plane.position.z = 0;
  group.add(plane);

  // --- Load texture asynchronously ---
  const imageUrl = config.imageUrl;
  if (imageUrl) {
    ctx.textureLoader.loadTexture(imageUrl).then((texture) => {
      material.map = texture;
      material.needsUpdate = true;
    });
  }

  // --- Text label ---
  const textOpts = {
    fontSize: headlineFontSize,
    color: paper,
    align: 'center',
    maxWidthPx: 250,
    letterSpacingPx: 2,
  };
  const textMesh = ctx.fontAtlas.createText(headlineText, textOpts);
  // Position text in front of plane, centered
  textMesh.position.set(0, 0, 0.01);
  // Scale text to fit plane width (approximate)
  const textScale = planeWidth * 0.7;
  textMesh.scale.set(textScale, textScale, textScale);
  group.add(textMesh);

  // --- Cleanup ---
  group.userData.cleanup = () => {
    geometry.dispose();
    material.dispose();
    // Dispose texture if loaded
    if (material.map) material.map.dispose();
    // Dispose text mesh resources
    textMesh.traverse((child) => {
      if (child.isMesh) {
        child.geometry?.dispose();
        if (Array.isArray(child.material)) {
          child.material.forEach(m => m.dispose());
        } else {
          child.material?.dispose();
        }
      }
    });
    // No GSAP timelines to kill
  };

  return group;
}
